-- Published immutable audit snapshot, private evidence bucket and current Quality catalogs.
-- No action-plan draft or publication data is stored by this migration.
begin;

create table public.published_audits (
  id uuid primary key,
  work_id uuid not null references public.access_works(id) on delete restrict,
  modulo text not null check (modulo in ('SEGURANCA','QUALIDADE')),
  model_id text not null check (model_id in ('security-it07-r02','quality-f175','quality-f176')),
  audit_date date not null,
  auditor_auth_user_id uuid not null references auth.users(id) on delete restrict,
  auditor_name text not null check (auditor_name = btrim(auditor_name) and char_length(auditor_name) between 2 and 200),
  final_score numeric(5,2) not null check (final_score between 0 and 10),
  catalog_revision_id uuid references public.audit_catalog_revisions(id) on delete restrict,
  catalog_version integer not null check (catalog_version >= 0),
  catalog_revision_label text not null check (char_length(btrim(catalog_revision_label)) between 1 and 80),
  criteria jsonb not null check (dialogo_private.valid_catalog_criteria(criteria)),
  responses jsonb not null check (jsonb_typeof(responses) = 'object'),
  evidence_files jsonb not null check (jsonb_typeof(evidence_files) = 'array'),
  report_file_name text not null check (dialogo_private.valid_catalog_filename(report_file_name,'pdf')),
  source_file_name text not null check (char_length(source_file_name) between 1 and 200),
  published_at timestamptz not null,
  created_at timestamptz not null default clock_timestamp(),
  constraint published_audits_model_module check (
    (model_id = 'security-it07-r02' and modulo = 'SEGURANCA')
    or (model_id in ('quality-f175','quality-f176') and modulo = 'QUALIDADE')
  )
);
create index published_audits_work_date on public.published_audits(work_id,modulo,audit_date desc);
alter table public.published_audits enable row level security;
revoke all on public.published_audits from public, anon, authenticated, service_role;

create trigger published_audits_immutable before update or delete on public.published_audits
  for each row execute function dialogo_private.reject_catalog_revision_mutation();
create trigger published_audits_no_truncate before truncate on public.published_audits
  for each statement execute function dialogo_private.reject_catalog_revision_mutation();

create function public.read_published_audits(
  p_profile text,
  p_engineering_scope text default null,
  p_administrative_scope text default null
) returns jsonb language plpgsql stable security definer set search_path = '' as $function$
declare v_result jsonb;
begin
  perform dialogo_private.lock_agenda_identity(auth.uid(),p_profile);
  if p_profile = 'ENGENHARIA' and (p_engineering_scope not in ('EQUIPE_OBRA','COORDENACAO') or not exists (
      select 1 from public.access_accounts a where a.auth_user_id = auth.uid()
        and p_engineering_scope = any(a.atuacoes_engenharia))) then
    raise exception using errcode = '42501', message = 'active_published_audit_profile_required';
  elsif p_profile = 'ADMINISTRATIVO' and p_administrative_scope not in ('SEGURANCA','QUALIDADE','GERAL') then
    raise exception using errcode = '42501', message = 'active_published_audit_profile_required';
  elsif p_profile not in ('ADMINISTRATIVO','AUDITOR_SEGURANCA','AUDITOR_QUALIDADE','ENGENHARIA')
    or (p_profile <> 'ENGENHARIA' and p_engineering_scope is not null)
    or (p_profile <> 'ADMINISTRATIVO' and p_administrative_scope is not null) then
    raise exception using errcode = '42501', message = 'active_published_audit_profile_required';
  end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',a.id,'workId',a.work_id,'modelId',a.model_id,'date',a.audit_date,
    'auditorId',a.auditor_auth_user_id,'auditor',a.auditor_name,'finalScore',a.final_score,
    'catalogRevisionId',a.catalog_revision_id,'catalogVersion',a.catalog_version,
    'catalogRevisionLabel',a.catalog_revision_label,
    'criteria',case when p_profile='ENGENHARIA' then (
      select jsonb_agg((c.value-array['configuredWeight','weightConfigurationId']) || '{"documentedWeight":null}'::jsonb order by c.ordinality)
      from jsonb_array_elements(a.criteria) with ordinality c(value,ordinality)
    ) else a.criteria end,
    'responses',case when p_profile='ENGENHARIA' then (
      select jsonb_object_agg(e.key,case when jsonb_typeof(e.value->'checks')='array' then
        jsonb_set(e.value,'{checks}',coalesce((select jsonb_agg(c.value-'weight' order by c.ordinality)
          from jsonb_array_elements(e.value->'checks') with ordinality c(value,ordinality)),'[]'::jsonb))
        else e.value end) from jsonb_each(a.responses) e
    ) else a.responses end,
    'evidenceFiles',a.evidence_files,'reportFileName',a.report_file_name,'publishedAt',a.published_at)
    order by a.audit_date desc,a.id),'[]'::jsonb) into v_result
  from public.published_audits a join public.access_works w on w.id = a.work_id
  where w.ativo and (
    (p_profile = 'ADMINISTRATIVO' and public.has_current_administrative_module(a.modulo)
      and (p_administrative_scope = 'GERAL' or p_administrative_scope = a.modulo))
    or (p_profile <> 'ADMINISTRATIVO' and exists (
      select 1 from public.access_grants g where g.auth_user_id = auth.uid()
        and g.perfil = p_profile and g.obra_id = a.work_id and g.modulo = a.modulo))
  );
  return v_result;
end;
$function$;
revoke all on function public.read_published_audits(text,text,text) from public,anon,authenticated,service_role;
grant execute on function public.read_published_audits(text,text,text) to authenticated;

create function public.can_read_published_audit_storage(p_work_id uuid,p_audit_id uuid)
returns boolean language sql stable security definer set search_path = '' as $function$
  select exists (select 1 from public.published_audits a join public.access_works w on w.id = a.work_id
    where a.id = p_audit_id and a.work_id = p_work_id and w.ativo and (
      public.is_current_access_administrator() or public.has_current_administrative_module(a.modulo)
      or exists (select 1 from public.access_grants g where g.auth_user_id = auth.uid()
        and g.obra_id = a.work_id and g.modulo = a.modulo)));
$function$;
revoke all on function public.can_read_published_audit_storage(uuid,uuid) from public,anon,authenticated,service_role;
grant execute on function public.can_read_published_audit_storage(uuid,uuid) to authenticated;

insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)
values ('published-audits','published-audits',false,41943040,array['image/png','image/jpeg','application/pdf'])
on conflict (id) do update set public = false,file_size_limit = excluded.file_size_limit,allowed_mime_types = excluded.allowed_mime_types;
create policy "published_audits_read_authorized" on storage.objects for select to authenticated
  using (bucket_id = 'published-audits'
    and (storage.foldername(name))[1] ~* '^[0-9a-f-]{36}$'
    and (storage.foldername(name))[2] ~* '^[0-9a-f-]{36}$'
    and public.can_read_published_audit_storage((storage.foldername(name))[1]::uuid,(storage.foldername(name))[2]::uuid));

