    values('quality-f176',v_version,'F.176/00 — critérios e FVS atualizados','Critérios quantitativos com observação por item verificado; evidências qualitativas múltiplas; seleção e pesos dos serviços FVS conforme Peso FVS.',
      $json$[{"id":"F176-F176-Q01","code":"01.01","text":"Verificar se o PQO está aprovado e atualizado no Autodoc Qualidade.","title":"Plano de Qualidade da Obra - PQO","group":"1. Controle de Qualidade","subgroup":"","source":"F176","locator":"tabela 2, linha 3","documentedWeight":0.3,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q02","code":"01.02","text":"Verificar se o projeto está atualizado incluindo, minimamente, questões de logística e produção (acessos e circulações de produtos, equipamentos e pessoas; áreas de produção e processamento, de escritórios, de armazenamento de produtos e de armazenamento de resíduos; localização de equipamentos de produção e transporte) e as áreas de vivência (instalações sanitárias, vestiário e local de refeições - obrigatórias; alojamento, cozinha, lavanderia, área de lazer e ambulatório - quando aplicáveis.","title":"Projeto de Canteiro","group":"1. Controle de Qualidade","subgroup":"","source":"F176","locator":"tabela 2, linha 4","documentedWeight":0.7,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q03","code":"01.03","text":"Verificar se os consumos de resíduos, energia e água do mês foram devidamente preenchidos. Comparar contas do mês com os valores preenchidos. Verificar também indicador quanto à meta de acordo com a área construída.","title":"Tabela de Consumo Mensal - F.107","group":"1. Controle de Qualidade","subgroup":"","source":"F176","locator":"tabela 2, linha 5","documentedWeight":0.4,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q04","code":"01.04","text":"Verificar se os equipamentos estão com etiquetas de identificação e devidamente mapeados na planilha de controle. Verificar validades das aferições. Verificar também a qualidade das trenas utilizadas.","title":"Planilha de Controle de Equipamentos de Medição - F.39","group":"1. Controle de Qualidade","subgroup":"","source":"F176","locator":"tabela 2, linha 6","do