    $json$[{"id":"F176-F176-Q01","code":"01.01","text":"Verificar se o PQO está aprovado e atualizado no Autodoc Qualidade.","title":"Plano de Qualidade da Obra - PQO","group":"1. Controle de Qualidade","subgroup":"","source":"F176","locator":"tabela 2, linha 3","documentedWeight":0.3,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q02","code":"01.02","text":"Verificar se o projeto está atualizado incluindo, minimamente, questões de logística e produção (acessos e circulações de produtos, equipamentos e pessoas; áreas de produção e processamento, de escritórios, de armazenamento de produtos e de armazenamento de resíduos; localização de equipamentos de produção e transporte) e as áreas de vivência (instalações sanitárias, vestiário e local de refeições - obrigatórias; alojamento, cozinha, lavanderia, área de lazer e ambulatório - quando aplicáveis.","title":"Projeto de Canteiro","group":"1. Controle de Qualidade","subgroup":"","source":"F176","locator":"tabela 2, linha 4","documentedWeight":0.7,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q03","code":"01.03","text":"Verificar se os consumos de resíduos, energia e água do mês foram devidamente preenchidos. Comparar contas do mês com os valores preenchidos. Verificar também indicador quanto à meta de acordo com a área construída.","title":"Tabela de Consumo Mensal - F.107","group":"1. Controle de Qualidade","subgroup":"","source":"F176","locator":"tabela 2, linha 5","documentedWeight":0.4,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q04","code":"01.04","text":"Verificar se os equipamentos estão com etiquetas de identificação e devidamente mapeados na planilha de controle. Verificar validades das aferições. Verificar também a qualidade das trenas utilizadas.","title":"Planilha de Controle de Equipamentos de Medição - F.39","group":"1. Controle de Qualidade","subgroup":"","source":"F176","locator":"tabela 2, linha 6","documentedWeight":0.2,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q05","code":"01.05","text":"Os objetivos estabelecidos pelo plano mensal de atividades estão sendo realizados (F.49).","title":"Plano Mensal de Atividades - F.49","group":"1. Controle de Qualidade","subgroup":"","source":"F176","locator":"tabela 2, linha 7","documentedWeight":0.2,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q06","code":"02.01","text":"Verificar se existe o controle de recebimento e aceitação de materiais devidamente preenchido nas FVMs.","title":"Ficha de Verificação de Materiais - FVM","group":"2. Armazenamento de Materiais","subgroup":"","source":"F176","locator":"tabela 2, linha 9","documentedWeight":0.3,"orientations":[],"verificationRule":"Dividido pela quantidade verificada"},{"id":"F176-F176-Q07","code":"02.02","text":"Verificar se o controle de validade dos materiais está sendo preenchido corretamente, conforme materiais presentes na obra.","title":"Controle do Prazo de Validade dos Materiais - F.99","group":"2. Armazenamento de Materiais","subgroup":"","source":"F176","locator":"tabela 2, linha 10","documentedWeight":0.3,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q08","code":"02.03","text":"Verificar se o acompanhamento semanal da TAM está sendo preenchido corretamente.","title":"Acompanhamento Semanal pela TAM - F.87","group":"2. Armazenamento de Materiais","subgroup":"","source":"F176","locator":"tabela 2, linha 11","documentedWeight":0.3,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q09","code":"02.04","text":"Verificar se os materiais estão identificados e armazenados conforme especificado na TAM.","title":"Armazenamento dos Materiais","group":"2. Armazenamento de Materiais","subgroup":"","source":"F176","locator":"tabela 2, linha 12","documentedWeight":1,"orientations":[],"verificationRule":"Dividido pela quantidade verificada"},{"id":"F176-F176-Q10","code":"03.01","text":"Verificar se atividades estão sendo realizadas conforme as especificações do projeto (elevações de alvenaria, vão de portas/janelas, etc.).","title":"Execução dos Serviços","group":"3. Execução dos Processos","subgroup":"","source":"F176","locator":"tabela 2, linha 14","documentedWeight":0.7,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q11","code":"03.02","text":"Verificar se os projetos disponíveis em campo estão com as revisões devidamente identificadas na F.110 e atuais conforme Autodoc Projetos.","title":"Planilha de Controle de Projetos em Obras - F.110","group":"3. Execução dos Processos","subgroup":"","source":"F176","locator":"tabela 2, linha 15","documentedWeight":0.3,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q12","code":"04.01","text":"Verificar a aderência dos procedimentos executivos com o que é falado pelos colaboradores.","title":"Entrevista com Colaboradores","group":"4. Treinamento","subgroup":"","source":"F176","locator":"tabela 2, linha 17","documentedWeight":0.2,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q13","code":"04.02","text":"Verificar se os colaboradores sabem explicar o que é a política da qualidade e o que é tratado nela.","title":"Política da Qualidade","group":"4. Treinamento","subgroup":"","source":"F176","locator":"tabela 2, linha 18","documentedWeight":0.2,"orientations":[],"verificationRule":"Dividido pela quantidade verificada"},{"id":"F176-F176-Q14","code":"04.03","text":"Verificar se todos os colaboradores entrevistados em campo possuem registros de treinamentos conforme a matriz de treinamentos presente no PQO.","title":"Registros dos Treinamentos","group":"4. Treinamento","subgroup":"","source":"F176","locator":"tabela 2, linha 19","documentedWeight":0.2,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q15","code":"05.01","text":"Verificar se o plano está atualizado, publicado e se as diretrizes estão sendo seguidas.","title":"Plano de Gerenciamento de Resíduos da Construção Civil - PGRCC","group":"5. Ambiente de Trabalho","subgroup":"","source":"F176","locator":"tabela 2, linha 21","documentedWeight":0.3,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q16","code":"05.02","text":"Verificar se a quantidade de caçambas indicada no SP Regula é a mesma presente na obra; verificar se o volume que saiu é o mesmo indicado na CTR.","title":"Controle de Transporte de Resíduos - CTR","group":"5. Ambiente de Trabalho","subgroup":"","source":"F176","locator":"tabela 2, linha 22","documentedWeight":0.2,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q17","code":"05.03","text":"Verificar se as caçambas estão devidamente identificadas e se os resíduos correspondem à identificação.","title":"Caçambas de Entulhos","group":"5. Ambiente de Trabalho","subgroup":"","source":"F176","locator":"tabela 2, linha 23","documentedWeight":0.2,"orientations":[],"verificationRule":"Conforme/Não Conforme"},{"id":"F176-F176-Q18","code":"05.04","text":"Aplicável a partir do momento que se inicia a alvenaria nos empreendimentos. Verificar se estão devidamente posicionadas e identificadas.","title":"Baia de Bags","group":"5. Ambiente de Trabalho","subgroup":"","source":"F176","locator":"tabela 2, linha 24","documentedWeight":0.2,"orientations":[],"verificationRule":"Dividido pela quantidade verificada"},{"id":"F176-F176-Q19","code":"05.05","text":"Verificar se as licenças das empresas responsáveis pelo destino final e transporte dos resíduos gerados estão sendo devidamente registradas na planilha de caracterização e quantificação de resíduos (F.124). Verificar também a validade das licenças.","title":"Caracterização e Quantificação de Resíduos - F.124","group":"5. Ambiente de Trabalho","subgroup":"","source":"F176","locator":"tabela 2, linha 25","documentedWeight":0.2,"orientations":[],"verifica